SELECT quantity_bucket, avg_unit_price, max_quantity FROM (SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(unit_price), 2) AS avg_unit_price, MAX(quantity) AS max_quantity FROM order_items WHERE unit_price >= 350 GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) AS agg WHERE max_quantity >= 7.5 ORDER BY avg_unit_price
